<?php if(!$influence): ?><p class="fine">Human-input disclosure was not collected for this historical result.</p><?php else: ?>
<aside class="<?=($influence['review_status']??'')==='needed'?'warning':'notice'?>" data-influence-status><strong><?=e(match($influence['review_status']??''){ 'needed'=>'Human influence disclosed — awaiting admin decision', 'approved'=>'Human influence reviewed — packet approved', 'rejected'=>'Human influence reviewed — packet rejected', 'reviewed'=>'Historical human influence review recorded', default=>'No substantive human influence declared' })?></strong><p class="fine">Self-reported by the AI and contributor. Approval does not authenticate an untouched conversation or establish scientific truth.</p><?php if(isset($influence['volunteer_declaration_scope'])): ?><p class="fine"><?=e($influence['volunteer_declaration_scope'])?></p><?php endif ?><details><summary>Human-input disclosures</summary><?php foreach(['human_interaction'=>'AI disclosure','human_disclosure'=>'Contributor disclosure'] as $key=>$label): ?><p><strong><?=e($label)?>:</strong> <?=e(str_replace('_',' ',$influence[$key]['level']??'Not recorded'))?></p><?=prose($influence[$key]['details']??'')?><?php endforeach ?><?php if(isset($influence['review_reason'])): ?><p><strong>Administrator decision:</strong> <?=e($influence['review_reason'])?> · <?=e($influence['reviewed_at_utc'])?> UTC</p><?php endif ?></details></aside><?php endif ?>
